import { expect, inject, it } from "vitest";

const baseUrl = inject("baseUrl");

async function analystCookie(): Promise<string> {
  const res = await fetch(new URL("/", baseUrl));
  return res.headers.get("set-cookie")!.split(";")[0]!;
}

// Focus Mode means there's always at most one active threat, generated by the
// server's own loop — we vote on whichever one is live rather than assuming
// we created it ourselves.
it("lets an analyst vote on the active threat", async () => {
  const cookie = await analystCookie();

  const stateRes = await fetch(new URL("/api/state", baseUrl), { headers: { cookie } });
  const state = (await stateRes.json()) as { active: { id: string } | null };
  expect(state.active, "a threat should always be active").toBeTruthy();

  const voteRes = await fetch(new URL(`/api/incidents/${state.active!.id}/vote`, baseUrl), {
    method: "POST",
    headers: { "content-type": "application/json", cookie },
    body: JSON.stringify({ severity: 4, likelihood: 3 }),
  });
  expect(voteRes.status).toBe(200);

  const afterVoteRes = await fetch(new URL("/api/state", baseUrl), { headers: { cookie } });
  const afterVote = (await afterVoteRes.json()) as {
    active: { id: string; votes: { severity: number; likelihood: number }[] } | null;
  };
  expect(afterVote.active?.id, "the active threat shouldn't have changed mid-test").toBe(state.active!.id);
  expect(afterVote.active?.votes, "the vote should be recorded against the active threat").toContainEqual(
    expect.objectContaining({ severity: 4, likelihood: 3 }),
  );
});

it("rejects a second vote from the same analyst on the same threat", async () => {
  const cookie = await analystCookie();

  const stateRes = await fetch(new URL("/api/state", baseUrl), { headers: { cookie } });
  const state = (await stateRes.json()) as { active: { id: string } | null };
  expect(state.active, "a threat should always be active").toBeTruthy();
  const incidentId = state.active!.id;

  const firstVote = await fetch(new URL(`/api/incidents/${incidentId}/vote`, baseUrl), {
    method: "POST",
    headers: { "content-type": "application/json", cookie },
    body: JSON.stringify({ severity: 6, likelihood: 6 }),
  });
  expect(firstVote.status).toBe(200);

  const secondVote = await fetch(new URL(`/api/incidents/${incidentId}/vote`, baseUrl), {
    method: "POST",
    headers: { "content-type": "application/json", cookie },
    body: JSON.stringify({ severity: 9, likelihood: 9 }),
  });
  expect(secondVote.status, "a second vote on the same threat should be rejected, not applied as an update").toBe(400);

  const afterRes = await fetch(new URL("/api/state", baseUrl), { headers: { cookie } });
  const after = (await afterRes.json()) as {
    active: { id: string; votes: { severity: number; likelihood: number }[] } | null;
  };
  if (after.active?.id === incidentId) {
    expect(
      after.active.votes,
      "the rejected second vote should not have overwritten the first",
    ).toContainEqual(expect.objectContaining({ severity: 6, likelihood: 6 }));
    expect(after.active.votes).not.toContainEqual(expect.objectContaining({ severity: 9, likelihood: 9 }));
  }
});

it("queues an analyst-reported threat behind the active one", async () => {
  const cookie = await analystCookie();

  const before = (await (await fetch(new URL("/api/state", baseUrl), { headers: { cookie } })).json()) as {
    queueLength: number;
  };

  const createRes = await fetch(new URL("/api/incidents", baseUrl), {
    method: "POST",
    headers: { "content-type": "application/json", cookie },
    body: JSON.stringify({
      title: "Spec test incident",
      description: "Created by spec/incidents.test.ts",
      category: "network",
    }),
  });
  expect(createRes.status).toBe(201);

  const after = (await (await fetch(new URL("/api/state", baseUrl), { headers: { cookie } })).json()) as {
    queueLength: number;
  };
  expect(after.queueLength, "the report should land in the queue, not go live immediately").toBe(before.queueLength + 1);
});
